var SLUGS=["what-is-cryogenics", "cryogenic-fluids", "refrigeration-and-liquefaction", "heat-transfer-and-insulation", "materials-at-low-temperature", "applications", "safety", "cryogens-and-their-properties", "hydrogen-and-helium", "superfluid-helium-he-ii", "mechanical-properties-and-thermal-contraction", "specific-heat-and-thermal-conduction", "superconductivity", "conduction-in-solids-at-low-temperature", "thermal-resistance-joints-and-thermal-links", "transient-conduction-and-cooldown", "natural-convection-and-stable-stratification", "convection-and-boiling-heat-transfer", "boiling-in-motion-bubbles-burnout-and-hysteresis", "gas-conduction-and-thermal-radiation", "counterflow-heat-exchangers-in-motion", "ideal-refrigerators-and-the-cost-of-cold", "the-joule-thomson-effect-in-motion", "linde-hampson-liquefier", "heat-exchanger-effectiveness", "precooled-and-dual-pressure-systems", "claude-system", "claude-family-and-system-comparison", "liquefier-cycles-in-motion", "liquefaction-cycles-on-the-t-s-diagram", "gas-separation-and-ideal-work", "mixtures-phase-diagrams-and-k-values", "rectification-columns-and-plate-calculations", "air-separation-and-distillation-in-motion", "cryocooler-fundamentals-and-the-stirling-cycle", "gifford-mcmahon-and-pulse-tube-coolers", "cryocoolers-in-motion", "the-stirling-cryocooler-cycle-on-p-v-and-t-s-diagrams", "cryogenic-insulation", "vacuum-technology", "cryogenic-instrumentation", "measuring-flow-pressure-and-liquid-level", "safety-in-cryogenics", "cryogenic-storage-and-boil-off", "piping-valves-and-transfer-lines", "pressure-drop-fittings-and-two-phase-flow", "cryostat-design", "designing-a-cryogenic-system", "pressure-relief-and-overpressure-safety", "thermoacoustic-oscillations-in-cryogenic-systems", "helium-ii-cryogenic-systems", "cryogenic-controls-and-plant-automation", "liquid-argon-detectors-and-dune", "superconducting-rf-cavities-for-accelerators", "cryogenics-for-dark-matter-and-the-cosmic-microwave-background", "below-1-kelvin-and-pumped-helium-refrigerators", "dilution-refrigerators", "magnetic-cooling-adr-pomeranchuk-and-nuclear-demagnetisation", "materials-and-thermometry-below-1-kelvin", "lab-building-a-cryostat-step-by-step", "lab-vacuum-and-leak-checking-in-practice", "lab-cooling-down-safely", "lab-calibrating-thermometers"];

