var CS=document.getElementById('ycs'),PS=document.getElementById('ycp'),IS=document.getElementById('yci'),BT=document.getElementById('ycg'),run=true,u=0,last=0,cur=null;
var X0=60,Y0=22,W=560,H=312,sx=function(s){return X0+(s+.3)/4.7*W},ty=function(T){return Y0+H-(T-55)/275*H};
var OPT={carnot:[['',' (fixed)']],ideal:[['','(none)']],lh:[['50','50 bar'],['100','100 bar'],['200','200 bar']],pc:[['100','100 bar'],['200','200 bar']],cl:[['40','40 bar']]};
function fillp(){var o=OPT[CS.value],k=PS.value;PS.innerHTML='';o.forEach(function(a){var e=document.createElement('option');e.value=a[0];e.textContent=a[1];PS.appendChild(e)});if(OPT[CS.value].some(function(a){return a[0]==k}))PS.value=k;else PS.value=CS.value=='lh'?'200':o[o.length-1][0];PS.disabled=o.length<2}
function sel(){var c=CS.value;cur=D.cyc[c];if(c=='lh'||c=='pc'||c=='cl')cur=cur[PS.value];cur.name=c;u=0;info()}
function info(){var c=CS.value,r=cur,h='',n='';
if(c=='carnot'){h='<div><b>'+r.COP+'</b><small>Carnot COP, Tc/(Th−Tc)</small></div><div><b>77 K / 300 K</b><small>cold and hot temperatures</small></div>';n='Ideal reversible refrigerator; the diagram is schematic in entropy but the temperatures are real.'}
else if(c=='ideal'){h='<div><b>'+r.W+' kJ/kg</b><small>ideal work per kg of liquid</small></div><div><b>100 %</b><small>of the gas is liquefied</small></div>';n='W = T1 (s1 − sf) − (h1 − hf), from the nitrogen equation of state.'}
else if(c=='lh'){h='<div><b>'+(r.y*100).toFixed(1)+' %</b><small>liquid yield y</small></div><div><b>'+r.T3+' K</b><small>temperature at the valve</small></div><div><b>'+r.W+' kJ/kg</b><small>compressor work per kg of gas</small></div><div><b>'+(r.FOM*100).toFixed(1)+' %</b><small>figure of merit</small></div>';n='Ideal counterflow exchanger, isothermal compressor at 300 K, no losses. Work per kg of liquid: '+r.Wl+' kJ.'}
else if(c=='pc'){h='<div><b>'+(r.y*100).toFixed(1)+' %</b><small>liquid yield y</small></div><div><b>'+r.Ta+' K</b><small>gas entering the precooler</small></div><div><b>'+(r.FOM*100).toFixed(1)+' %</b><small>figure of merit (compressor only)</small></div><div><b>'+(r.FOM2*100).toFixed(1)+' %</b><small>including an ideal precooler</small></div>';n='Precooler at 230 K, ideal exchangers. The precooler work is taken as that of a Carnot refrigerator between 300 K and 230 K.'}
else{h='<div><b>'+r.Te+' K</b><small>expander inlet</small></div><div><b>'+r.Tx+' K</b><small>expander exhaust, 1 bar</small></div><div><b>'+r.T3+' K</b><small>temperature at the valve</small></div>';n='Schematic: expander efficiency 0.75; the valve inlet is chosen so that 10 % of the throttled stream is liquid. Not a solved plant; see the Claude lesson for yields.'}
document.getElementById('yco').innerHTML=h.replace(/%/g,'%');document.getElementById('ycn').textContent=n+' Nitrogen properties from the reference equation of state; entropy measured from saturated liquid at 1 atm.'}
function len(p){var a=[0],i;for(i=1;i<p.length;i++)a.push(a[i-1]+Math.hypot(sx(p[i][0])-sx(p[i-1][0]),ty(p[i][1])-ty(p[i-1][1])));return a}
function at(p,L,f){var tot=L[L.length-1],d=f*tot,i=1;while(i<L.length-1&&L[i]<d)i++;var r=(d-L[i-1])/((L[i]-L[i-1])||1);return [p[i-1][0]+(p[i][0]-p[i-1][0])*r,p[i-1][1]+(p[i][1]-p[i-1][1])*r,i]}
function path(a){return a.map(function(p,i){return (i?'L':'M')+sx(p[0]).toFixed(1)+','+ty(p[1]).toFixed(1)}).join('')}
function frame(ts){var t=(ts||0)/1000,dt=last?Math.min(.05,t-last):0;last=t;if(run&&!RM)u=(u+dt/14)%1;
var o='',i,c=CS.value,r=cur;
o+=ax(X0,Y0,W,H);[60,100,150,200,250,300].forEach(function(T){o+=tx(X0-4,ty(T)+4,T,'end',10)+'<line x1='+X0+' y1='+ty(T).toFixed(1)+' x2='+(X0+W)+' y2='+ty(T).toFixed(1)+' style=stroke:var(--muted);opacity:.1></line>'});
[0,1,2,3,4].forEach(function(s){o+=tx(sx(s),Y0+H+14,s,'middle',10)});
o+=tx(X0+W/2,Y0+H+30,'entropy s (kJ/kg·K), measured from saturated liquid at 1 atm','middle',10.5,'var(--muted)')+tx(14,Y0+H/2,'T (K)','middle',10.5,'var(--muted)');
/* dome */
var dl=D.dome.map(function(a){return [a[0],a[2]]}),dg=D.dome.map(function(a){return [a[1],a[2]]}).reverse();
o+='<path d="'+path(dl.concat(dg))+'Z" style=fill:#1c7ed6;fill-opacity:.1;stroke:#1c7ed6;stroke-width:1.5></path>'+tx(sx(1.4),ty(98),'two-phase','middle',10.5,'#1c7ed6');
/* isobars */
var hp=(c=='carnot'||c=='ideal')?[]:['1',PS.value];
hp.forEach(function(p,j){var a=D.isobars[p];if(!a)return;o+='<path d="'+path(a)+'" style=fill:none;stroke:var(--muted);stroke-width:1;stroke-dasharray:3 3;opacity:.8></path>';var q=a[a.length-1];o+=tx(sx(q[0])+3,ty(q[1])-3,p+' bar','start',10,'var(--muted)')});
if(IS.checked)D.isenth.forEach(function(a){o+='<path d="'+path(a)+'" style=fill:none;stroke:#2f9e44;stroke-width:1.2;opacity:.8></path>'});
if(IS.checked)o+=tx(sx(3.9),ty(150),'isenthalps','start',10.5,'#2f9e44');
/* cycle */
var pts=r.pts,L=len(pts),k;
o+='<path d="'+path(pts)+'" style=fill:none;stroke:var(--accent);stroke-width:2.8></path>';
if(c=='cl'){var e=r.pts;}
r.lab.forEach(function(l){var p=pts[l[0]];o+=dot(sx(p[0]),ty(p[1]),'var(--accent)',4.5)+'<text x='+(sx(p[0])+7).toFixed(1)+' y='+(ty(p[1])-7).toFixed(1)+' style="font-size:12px;font-weight:700;fill:var(--text);paint-order:stroke;stroke:var(--bg,#fff);stroke-width:3px">'+l[1]+'</text>'});
if(r.f){o+=dot(sx(0),ty(77.35),'#1c7ed6',5)+tx(sx(0)-6,ty(77.35)+14,'liquid','end',10.5,'#1c7ed6')}
var q=at(pts,L,u),ci=q[2],stp='',li;for(li=0;li<r.lab.length;li++){if(ci<=r.lab[li][0]){stp=r.lab[li][2];break}}
o+=dot(sx(q[0]),ty(q[1]),'#fff',8)+dot(sx(q[0]),ty(q[1]),'var(--accent)',5.5);
o+=tx(X0+W/2,12,stp,'middle',11);
sc.innerHTML=o;if(!RM)RAF2=requestAnimationFrame(frame)}
function upd(){sel();cancelAnimationFrame(RAF2);frame(0)}
CS.onchange=function(){fillp();upd()};PS.onchange=upd;IS.onchange=function(){if(RM){cancelAnimationFrame(RAF2);frame(0)}};
